// Construit la requête /chat/completions pour n'importe quelle API compatible OpenAI.
// Entrée : { llm (section de config), niveau: 'rapide'|'principal', system, user, schema_name, schema }
const input = $input.first().json;
const llm = input.llm || {};
const baseUrl = String(llm.base_url || '').trim().replace(/\/+$/, '');
const model = input.niveau === 'rapide' && llm.modele_rapide ? llm.modele_rapide : llm.modele;
if (!baseUrl || !model) {
  throw new Error('LLM non configuré : renseignez « llm.base_url » et « llm.modele » dans config/veille.json.');
}
const mode = ['json_schema', 'json_object', 'aucun'].includes(llm.format_json) ? llm.format_json : 'json_schema';

const system = `${input.system}

## Format de sortie
Réponds UNIQUEMENT avec un objet JSON valide, sans texte avant ou après et sans bloc de code. Il doit respecter ce schéma JSON (les champs « description » précisent le contenu attendu) :
${JSON.stringify(input.schema)}`;

const body = {
  model,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: input.user },
  ],
};
if (llm.temperature !== null && llm.temperature !== undefined && llm.temperature !== '') body.temperature = Number(llm.temperature);
if (llm.max_tokens) body[llm.parametre_max_tokens || 'max_tokens'] = Number(llm.max_tokens);
if (mode === 'json_schema') {
  body.response_format = { type: 'json_schema', json_schema: { name: input.schema_name || 'reponse', strict: true, schema: input.schema } };
} else if (mode === 'json_object') {
  body.response_format = { type: 'json_object' };
}
Object.assign(body, llm.parametres_supplementaires || {}, input.niveau === 'rapide' ? llm.parametres_rapide || {} : {});

const budget = Math.max(1, Number(input.niveau === 'rapide' ? llm.delai_rapide_secondes ?? llm.delai_max_secondes : llm.delai_max_secondes) || 180) * 1000;
return [{
  json: {
    url: `${baseUrl}/chat/completions`,
    body,
    timeout_ms: budget,
    deadline: Date.now() + budget,
    tentative: 1,
    correction: false,
    usage: {},
    schema: input.schema,
    tache: input.schema_name || 'reponse',
    mode,
  },
}];

// Une seule boucle : erreurs temporaires, format refusé, puis au plus une correction JSON.
// Tous les essais partagent le même budget de temps.
// ── Lecture robuste des réponses d'une API compatible OpenAI (/chat/completions) ──

function llmHttpError(err) {
  // Élément produit par le nœud HTTP en mode « continuer en cas d'erreur »
  const e = err && typeof err === 'object' ? err : { message: String(err) };
  const code = Number(e.httpCode || e.status || e.statusCode || (e.context && e.context.httpCode)) || null;
  const detail = [e.message, e.description].filter(Boolean).join(' — ');
  return { code, detail: detail.slice(0, 800) || 'erreur inconnue' };
}

function llmContent(resp) {
  if (typeof resp === 'string') {
    try { resp = JSON.parse(resp); } catch (e) { throw new Error('Réponse LLM illisible : ' + resp.slice(0, 300)); }
  }
  const choice = resp && Array.isArray(resp.choices) ? resp.choices[0] : null;
  if (!choice) throw new Error('Réponse LLM sans « choices » : ' + JSON.stringify(resp).slice(0, 500));
  const msg = choice.message || {};
  if (msg.refusal) throw new Error('Le modèle a refusé de répondre : ' + msg.refusal);
  let content = msg.content;
  if (Array.isArray(content)) content = content.map(p => (typeof p === 'string' ? p : p.text || '')).join('');
  return { content: String(content ?? ''), finish: choice.finish_reason || null, usage: resp.usage || {}, model: resp.model || null };
}

function llmParseJson(text) {
  let t = text.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) t = fence[1].trim();
  try { return JSON.parse(t); } catch (e) { /* on tente d'isoler l'objet ci-dessous */ }
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('aucun objet JSON dans la réponse');
  return JSON.parse(t.slice(start, end + 1));
}

// Valide un sous-ensemble de JSON Schema et corrige les écarts de type bénins
// ("7" -> 7, "true" -> true, valeur d'énumération mal cassée, chaîne seule -> liste).
function llmValidate(schema, value, path, errors) {
  const type = schema.type;
  if (type === 'object') {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) { errors.push(`${path} doit être un objet`); return value; }
    for (const key of schema.required || []) if (!(key in value)) errors.push(`${path}.${key} est manquant`);
    for (const [key, sub] of Object.entries(schema.properties || {})) {
      if (key in value) value[key] = llmValidate(sub, value[key], `${path}.${key}`, errors);
    }
    return value;
  }
  if (type === 'array') {
    const items = schema.items || {};
    if (typeof value === 'string' && items.type === 'string') value = value.trim() ? [value] : [];
    if (!Array.isArray(value)) { errors.push(`${path} doit être une liste`); return value; }
    if (schema.minItems !== undefined && value.length < schema.minItems) errors.push(`${path} : au moins ${schema.minItems} éléments`);
    if (schema.maxItems !== undefined && value.length > schema.maxItems) errors.push(`${path} : au plus ${schema.maxItems} éléments`);
    return value.map((v, i) => llmValidate(items, v, `${path}[${i}]`, errors));
  }
  if (type === 'integer' || type === 'number') {
    const n = typeof value === 'string' && value.trim() ? Number(value.trim()) : value;
    if (typeof n !== 'number' || !Number.isFinite(n)) { errors.push(`${path} doit être un nombre`); return value; }
    if (type === 'integer' && !Number.isInteger(n)) errors.push(`${path} doit être un entier`);
    if (schema.minimum !== undefined && n < schema.minimum) errors.push(`${path} doit être ≥ ${schema.minimum}`);
    if (schema.maximum !== undefined && n > schema.maximum) errors.push(`${path} doit être ≤ ${schema.maximum}`);
    return n;
  }
  if (type === 'boolean') {
    if (value === 'true' || value === 'false') return value === 'true';
    if (typeof value !== 'boolean') errors.push(`${path} doit être un booléen`);
    return value;
  }
  if (type === 'string') {
    if (typeof value === 'number') value = String(value);
    if (typeof value !== 'string') { errors.push(`${path} doit être une chaîne`); return value; }
    if (schema.minLength && value.trim().length < schema.minLength) errors.push(`${path} est vide ou trop court`);
    if (schema.enum && !schema.enum.includes(value)) {
      const hit = schema.enum.find(e => e.toLowerCase() === value.trim().toLowerCase());
      if (hit) return hit;
      errors.push(`${path} doit valoir l'une de : ${schema.enum.join(', ')}`);
    }
    return value;
  }
  return value;
}

function llmAnalyse(resp, schema) {
  const { content, finish, usage, model } = llmContent(resp);
  const errors = [];
  let data;
  try { data = llmParseJson(content); } catch (e) { errors.push('JSON invalide : ' + e.message); }
  if (!errors.length) data = llmValidate(schema, data, '$', errors);
  if (errors.length && finish === 'length') {
    throw new Error('Réponse LLM tronquée (limite de tokens atteinte) : augmentez « llm.max_tokens » dans config/veille.json.');
  }
  return { ok: errors.length === 0, data, errors, content, usage, model };
}

function llmSumUsage(...all) {
  const out = { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
  for (const u of all) for (const k of Object.keys(out)) out[k] += Number(u && u[k]) || 0;
  return out;
}

const req = $('Requête en cours').first().json;
const resp = $input.first().json;
const status = Number(resp.statusCode) || 0;
let body = resp.body;
try { if (typeof body === 'string') body = JSON.parse(body); } catch (e) { /* llmAnalyse signalera la réponse illisible */ }
const fail = detail => { throw new Error(`Appel LLM en échec (${req.tache}) : ${detail}`); };
function retry(changes, motif, wait = 0) {
  const remaining = req.deadline - Date.now() - wait * 1000;
  if (remaining < 1000) fail(`budget de temps épuisé — ${motif}`);
  return [{ json: { ...req, ...changes, ok: false, motif, wait_seconds: wait, tentative: req.tentative + 1 } }];
}

if (resp.error || status >= 400) {
  // Une page HTML vient d'un intermédiaire (proxy sortant, passerelle), pas de l'API du LLM : on la résume.
  const page = typeof body === 'string' && /^\s*<(!doctype|html)/i.test(body);
  const hote = String(req.url).replace(/^https?:\/\//, '').split(/[/:]/)[0];
  const squid = resp.headers?.['x-squid-error'];
  const { detail } = page
    ? { detail: `${squid ? `le proxy sortant n'a pas pu joindre ${hote} (${squid})` : `page HTML reçue au lieu de l'API de ${hote} (« ${((body.match(/<title>([^<]*)/i) || [])[1] || 'sans titre').trim()} »)`}. Derrière un proxy sortant, un hôte interne se déclare dans OUTBOUND_NO_PROXY (.env), puis « make up »` }
    : llmHttpError(resp.error || body?.error || { message: String(body ?? '') });
  const motif = `HTTP ${status || '?'} — ${detail}`;
  if ((!status || status === 429 || status >= 500) && req.tentative < 3) {
    const header = resp.headers?.['retry-after'];
    const seconds = Number(header);
    const wait = header && !Number.isFinite(seconds) ? (Date.parse(header) - Date.now()) / 1000 : seconds;
    return retry({}, motif, Math.max(5, Math.ceil(wait) || 0));
  }
  const formatIssue = [400, 422].includes(status) && req.body.response_format
    && /response_format|json_schema|json_object|grammar|structured output/i.test(detail);
  if (!formatIssue) fail(motif);
  const next = { ...req.body };
  if (next.response_format.type === 'json_schema') next.response_format = { type: 'json_object' };
  else delete next.response_format;
  return retry({ body: next }, `Format JSON refusé : ${detail}`);
}

const r = llmAnalyse(body, req.schema);
const usage = llmSumUsage(req.usage, r.usage);
if (r.ok) return [{ json: { ok: true, data: r.data, usage, model: r.model, corrige: req.correction, tentatives: req.tentative } }];
if (req.correction) fail(`JSON invalide après correction : ${r.errors.slice(0, 5).join(' ; ')}`);
return retry({
  correction: true,
  usage,
  body: { ...req.body, messages: [
    ...req.body.messages,
    { role: 'assistant', content: r.content.slice(0, 20000) },
    { role: 'user', content: `Corrige ces erreurs :\n- ${r.errors.slice(0, 15).join('\n- ')}\nRenvoie UNIQUEMENT l'objet JSON complet conforme au schéma.` },
  ] },
}, r.errors.slice(0, 5).join(' ; '));
